#!/usr/bin/env bash
# ============================================================================
# RAGWire Studio — self-extracting installer
#
# Usage:
#   ./ragwire-studio-installer-vX.Y.Z.sh [--install-dir DIR] [--port PORT]
#                                        [--no-build] [--yes] [--help]
#
# It verifies Docker + Compose v2, extracts the bundled application, keeps an
# existing .env on upgrades (or generates one with a fresh JWT_SECRET_KEY),
# builds the images and starts the stack.
# ============================================================================
set -euo pipefail

ARGS="$*"
INSTALLER="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"

if ! command -v tar >/dev/null 2>&1 || ! command -v base64 >/dev/null 2>&1; then
  echo "ERROR: 'tar' and 'base64' are required to unpack this installer." >&2
  exit 1
fi

MARKER_LINE="$(grep -n '^__RAGWIRE_PAYLOAD__' "$INSTALLER" | tail -1 | cut -d: -f1)"
if [ -z "$MARKER_LINE" ]; then
  echo "ERROR: installer payload marker not found (file is truncated)." >&2
  exit 1
fi

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

echo "Extracting RAGWire Studio payload…"
tail -n +$((MARKER_LINE + 1)) "$INSTALLER" | base64 -d | tar -xzf - -C "$TMP"

if [ ! -f "$TMP/scripts/install.sh" ]; then
  echo "ERROR: payload is missing scripts/install.sh" >&2
  exit 1
fi

chmod +x "$TMP/scripts"/*.sh 2>/dev/null || true
RAGWIRE_PAYLOAD_DIR="$TMP" bash "$TMP/scripts/install.sh" $ARGS

# Never let bash fall through into the base64 payload appended below.
exit 0

__RAGWIRE_PAYLOAD__
